const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function row(x={},photos=[]){const input=(key,label,type='text',required=false,max=300)=>`<label>${label}<input data-event-field="${key}" type="${type}" value="${esc(x[key])}" ${required?'required':''} maxlength="${max}"></label>`;
 return `<fieldset class="event-editor-row" data-event-id="${esc(x.id||crypto.randomUUID())}"><legend>Evento</legend>${input('name','Nome do evento','text',true,120)}<div class="fields">${input('date','Data de início','date',true)}${input('time','Horário de início','time',true)}${input('endDate','Data de encerramento · opcional','date')}${input('endTime','Horário de encerramento · opcional','time')}</div><p class="helper">Horário de Brasília. Preencha os dois campos de encerramento ou deixe ambos vazios.</p>${input('venue','Local / endereço do evento','text',true)}<label>Sobre o evento<textarea data-event-field="description" required minlength="10" maxlength="3000">${esc(x.description)}</textarea></label><label>Valor do ingresso em R$ · 0 = gratuito; vazio = sob consulta<input data-event-field="price" type="number" min="0" max="1000000" step="0.01" value="${x.priceCents==null?'':x.priceCents/100}"></label><label>Condições · idade, acesso, o que inclui e cancelamento<textarea data-event-field="conditions" maxlength="3000">${esc(x.conditions)}</textarea></label><label>Imagem do evento<select data-event-field="photoId"><option value="">Usar capa do negócio</option>${photos.map((p,i)=>{const id=typeof p==='string'?p:p.id;return `<option value="${esc(id)}" ${x.photoId===id?'selected':''}>Foto ${i+1}</option>`;}).join('')}</select></label><label><input type="checkbox" data-event-field="available" ${x.available!==false?'checked':''}> Exibir na agenda quando o negócio estiver publicado</label><button type="button" class="chip p-button secondary" data-remove-event>Remover evento</button></fieldset>`;}
export function mountEvents(host,events=[],getPhotos=()=>[]){host.innerHTML='<p>O negócio é o organizador. Cadastre cada evento separadamente, com sua programação e condições. Eventos encerrados saem da agenda automaticamente. A participação depende da confirmação do organizador.</p><div data-event-list>'+events.map(x=>row(x,getPhotos())).join('')+'</div><button type="button" class="chip p-button secondary" data-add-event>Adicionar evento</button><p role="status" data-event-status></p>';host.addEventListener('click',e=>{if(e.target.closest('[data-add-event]')){const list=host.querySelector('[data-event-list]');if(list.children.length>=30){host.querySelector('[data-event-status]').textContent='Limite de 30 eventos por negócio.';return;}list.insertAdjacentHTML('beforeend',row({},getPhotos()));}e.target.closest('[data-remove-event]')?.closest('[data-event-id]').remove();});}
export function readEvents(form){return [...form.querySelectorAll('[data-event-id]')].map(el=>{const v=Object.fromEntries([...el.querySelectorAll('[data-event-field]')].map(i=>[i.dataset.eventField,i.type==='checkbox'?i.checked:i.value]));const {price,...rest}=v;return {id:el.dataset.eventId,...rest,priceCents:price===''?null:Math.round(Number(price)*100)};});}
export function refreshEventPhotos(form,photos){for(const select of form.querySelectorAll('[data-event-field=photoId]')){const value=select.value;select.innerHTML='<option value="">Usar capa do negócio</option>'+photos.map((p,i)=>{const id=typeof p==='string'?p:p.id;return `<option value="${esc(id)}" ${id===value?'selected':''}>Foto ${i+1}</option>`;}).join('');}}
